const normalize=s=>String(s).toLowerCase().normalize('NFKD').replace(/[’']/g,'').replace(/[^a-zа-яё0-9]/g,'');
export function parseImport(text,games){
 let entries=[];
 try{const j=JSON.parse(text);const list=j.response?.games||j.games||(Array.isArray(j)?j:null);if(list)entries=list.map(x=>({id:Number(x.appid||x.id)||null,label:x.name||String(x.appid||x.id||'')}));}catch{}
 if(!entries.length){const manifest=[...text.matchAll(/"appid"\s*"(\d+)"/gi)];if(manifest.length)entries=manifest.map(m=>({id:Number(m[1]),label:`Steam App ID ${m[1]}`}));else entries=text.split(/[\n;,]+/).map(s=>s.trim()).filter(Boolean).map(s=>{const match=s.match(/(?:appmanifest_|\/app\/)(\d+)(?:\D|$)/i);return {id:/^\d+$/.test(s)?Number(s):match?Number(match[1]):null,label:s};});}
 const ids=new Set(),unknown=[],ambiguous=[];let duplicates=0;
 for(const entry of entries){let found=[];if(entry.id)found=games.filter(g=>g.id===entry.id);else{const n=normalize(entry.label);found=games.filter(g=>[g.title,...g.aliases].some(a=>normalize(a)===n));if(!found.length)found=games.filter(g=>[g.title,...g.aliases].some(a=>normalize(a).length>=5&&n.includes(normalize(a))));}
 if(found.length===1){if(ids.has(found[0].id))duplicates++;ids.add(found[0].id);}else if(found.length>1)ambiguous.push({label:entry.label,candidates:found.map(g=>g.id)});else unknown.push(entry.label);
 }
 return {ids:[...ids],unknown,ambiguous,duplicates,processed:entries.length};
}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function importMarkup(count,isDesktop){return `<div class="modal-pad import-guide"><h2>Импорт библиотеки</h2><p>Добавь игры, которые у тебя уже есть. Перед сохранением проверь список — ничего не добавится без твоего выбора.</p><div class="import-methods"><section><h3>Из Steam</h3><ol class="import-steps"><li><b>Найди папку библиотеки</b><span>Обычно это <code>C:\\Program Files (x86)\\Steam\\steamapps</code>. Для другого диска путь может выглядеть как <code>D:\\SteamLibrary\\steamapps</code>.</span></li><li><b>Выбери манифесты игр</b><span>Нужны файлы <code>appmanifest_*.acf</code> рядом с папкой <code>common</code>. Например, <code>appmanifest_730.acf</code>. Это небольшие текстовые файлы, не сами игры.</span></li><li><b>Проверь и добавь</b><span>Убери галочки с лишних игр. Уже добавленные игры не продублируются.</span></li></ol><div class="inline-actions">${isDesktop?'<button class="btn primary" data-action="scan-steam">Выбрать папку Steam</button>':''}<label class="btn file-picker">Выбрать файлы .acf<input type="file" id="steam-files" accept=".acf,.txt,.json" multiple aria-label="Файлы библиотеки Steam"></label></div><details><summary>Не могу найти steamapps</summary><p>В Steam открой настройки хранилища и посмотри путь библиотеки. Другой способ: свойства установленной игры → установленные файлы → обзор. Из папки игры поднимись на два уровня: игра → common → steamapps.</p><p>Если библиотеки на нескольких дисках, импортируй каждую отдельно. У неустановленных игр манифеста может не быть.</p></details></section><section><h3>Из списка названий</h3><p>Одно название, ссылка Steam или App ID на строку. Можно вставить JSON-список с полями <code>appid</code> и <code>name</code>.</p><textarea id="import-text" aria-label="Список игр" placeholder="Ведьмак 3&#10;Stardew Valley&#10;https://store.steampowered.com/app/730/"></textarea><div class="inline-actions"><button class="btn primary" data-action="recognize">Распознать список</button><button class="btn" data-action="import-example">Вставить пример</button></div><p class="info-note">Импорт сверяется с ${count} играми текущего каталога. Если игра не найдена, она появится в отдельном списке, а не исчезнет без объяснения.</p></section></div><div id="import-result" aria-live="polite"></div><details class="import-privacy"><summary>Что импорт видит и где сохраняет данные</summary><p>Выбранные файлы обрабатываются на устройстве. Пароль, Steam Guard и API-ключ не нужны. Импорт не входит в аккаунт Steam, не сканирует рабочий стол и не получает всю историю покупок. Отправки файлов на сервер нет.</p><p>Библиотека сохраняется в локальном профиле NEXTPLAY. Для переноса между сайтом и приложением используй резервную копию в профиле.</p></details></div>`;}
export function importResultMarkup(result,games,owned){const fresh=result.ids.filter(id=>!owned.includes(id));return `<div class="import-summary"><h3>Результат распознавания</h3><p>Обработано: ${result.processed} · найдено: ${result.ids.length} · уже в библиотеке: ${result.ids.length-fresh.length}${result.duplicates?' · повторов: '+result.duplicates:''}</p></div>${result.ids.map(id=>{const g=games.find(g=>g.id===id),exists=owned.includes(id);return `<label class="import-item"><input type="checkbox" data-import-id="${id}" ${exists?'disabled':'checked'}><img src="${g.image}" alt=""><span>${esc(g.title)}</span><span>${exists?'Уже есть':'Новая'}</span></label>`;}).join('')}${fresh.length?`<button class="btn primary" data-action="confirm-import">Добавить выбранные (${fresh.length})</button>`:''}${result.ambiguous.length?`<details class="import-unmatched" open><summary>Неоднозначные названия: ${result.ambiguous.length}</summary><ul>${result.ambiguous.map(a=>`<li>${esc(a.label)} — уточни: ${a.candidates.map(id=>esc(games.find(g=>g.id===id).title)).join(' или ')}</li>`).join('')}</ul></details>`:''}${result.unknown.length?`<details class="import-unmatched" open><summary>Не найдены в каталоге: ${result.unknown.length}</summary><ul>${result.unknown.slice(0,50).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>Проверь полное название или App ID. Новые игры могут ещё не входить в каталог.</p></details>`:''}${!result.processed?'<p class="notice">Вставь хотя бы одно название или выбери файлы Steam.</p>':''}`;}
